contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(bytes32 hash, bool lock, uint waitBlocks) public payable {
        require(address(this).balance >= 1 ether);
        require(waitBlocks >= 1);
        uint balanceBeforeLock = address(this).balance;

        if (lock) {
            c.lockInGuess{value: 1 ether}(hash);
        }

        uint beforeGuessBlock = block.number;
        uint cBalanceBeforeSettle = address(c).balance;
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }

        if (!lock) {
            assert(reverted);
            assert(address(this).balance == balanceBeforeLock);
            assert(address(c).balance == cBalanceBeforeSettle);
        } else {
            // A guess was locked in at beforeGuessBlock, so settle() must not revert
            // only once the block number has advanced beyond the guess block.
            assert(reverted == (block.number <= beforeGuessBlock + 1));
        }

        assert(reverted || address(c).balance == cBalanceBeforeSettle - 2 ether || address(c).balance == cBalanceBeforeSettle);
    }

    receive() external payable {}
}

